final class WPVDMCP_Parity_Insights {
	public static function definitions(){return array(self::tool('inspect_media','Inspect safe Media Library metadata and optionally extract bounded PDF text through a user-owned provider/filter.',array('attachment_id'=>self::intp('Attachment ID.',true),'max_text_chars'=>self::intp('PDF text limit, default 12000, max 50000.'))),self::tool('site_intelligence','Return bounded WordPress/WPVibe environment diagnostics without filesystem paths or secrets.',array()),self::tool('live_reload_status','Report whether WPVibe live-reload polling is available on this site.',array()),self::tool('seo_audit','Run a read-only HTML SEO audit for title, description, canonical, robots, headings, schema and image alt text.',array('path'=>self::strp('Site-relative path.',true))),self::tool('integration_capabilities','Detect native builder/theme/block capabilities without guessing proprietary storage formats.',array()),self::tool('page_audit','Run Lighthouse/PageSpeed-style analysis only through a configured user-owned provider. No WPVibe cloud credential is embedded.',array('url'=>self::strp('Public URL.',true),'strategy'=>self::strp('Optional mobile or desktop strategy.'))),self::tool('search_images','Search stock images only through a configured user-owned provider. No WPVibe/Unsplash private key is embedded.',array('query'=>self::strp('Search query.',true),'per_page'=>self::intp('Maximum results.'))),self::tool('render_browser','Render a page with JavaScript only through a configured user-owned browser provider.',array('url'=>self::strp('URL to render.',true),'wait_for'=>self::strp('Optional selector or readiness hint.'))));}
	public static function handles($name){foreach(self::definitions()as$d){if($d['name']===$name)return true;}return false;}
	public static function execute($name,$args){$args=is_array($args)?$args:array();switch($name){case'inspect_media':return self::inspect_media($args);case'site_intelligence':return self::site_intelligence();case'live_reload_status':return self::live_reload_status();case'seo_audit':return self::seo_audit($args);case'integration_capabilities':return self::integrations();case'page_audit':case'search_images':case'render_browser':return self::provider($name,$args);}return new WP_Error('unknown_insight_tool','Unknown insight/provider tool.',array('status'=>404));}
	private static function inspect_media($args){$id=absint($args['attachment_id']??0);if(!$id)return new WP_Error('invalid_attachment','attachment_id is required.',array('status'=>400));$media=null;if(isset($GLOBALS['wpvdmcp_media_items'][$id]))$media=$GLOBALS['wpvdmcp_media_items'][$id];elseif(function_exists('get_post')){$p=get_post($id);if($p)$media=array('id'=>$id,'title'=>$p->post_title,'mime_type'=>function_exists('get_post_mime_type')?get_post_mime_type($id):'','url'=>function_exists('wp_get_attachment_url')?wp_get_attachment_url($id):'');}if(!is_array($media))return new WP_Error('media_not_found','Attachment not found.',array('status'=>404));foreach(array('file','path','attached_file','metadata_path')as$k)unset($media[$k]);$out=array('media'=>$media);if('application/pdf'===($media['mime_type']??'')){$max=max(100,min(50000,absint($args['max_text_chars']??12000)));$text=self::provider_value('pdf_text',array('attachment_id'=>$id,'media'=>$media));if(is_string($text)&&$text!==''){$out['text']=substr($text,0,$max);$out['text_truncated']=strlen($text)>$max;}else{$out['text_available']=false;$out['note']='No PDF text provider is configured.';}}return $out;}
	private static function site_intelligence(){global $wp_version;$out=array('wordpress_version'=>isset($wp_version)?(string)$wp_version:WPVDMCP_Compatibility::wordpress_version(),'wpvibe_version'=>defined('WPVIBE_VERSION')?WPVIBE_VERSION:null,'direct_mcp_version'=>defined('WPVDMCP_VERSION')?WPVDMCP_VERSION:null,'php_version'=>PHP_VERSION,'rest_route_count'=>count(WPVDMCP_Compatibility::routes()),'abilities_available'=>WPVDMCP_Compatibility::route_exists('/wp-abilities/v1/abilities'),'live_reload_available'=>WPVDMCP_Compatibility::route_exists('/wpvibe/v1/last-change'),'integrations'=>self::integrations());if(WPVDMCP_Compatibility::route_exists('/wpvibe/v1/site-info')){$site=WPVDMCP_Tools::dispatch('GET','/wpvibe/v1/site-info');if(!is_wp_error($site)&&isset($site['data'])&&is_array($site['data'])){foreach(array('site_health','performance','plugins','themes','active_theme','site_url','home_url','wordpress_address')as$key){if(array_key_exists($key,$site['data']))$out[$key]=$site['data'][$key];}}}return $out;}
	private static function live_reload_status(){return array('available'=>WPVDMCP_Compatibility::route_exists('/wpvibe/v1/last-change'),'route'=>'/wpvibe/v1/last-change','transport'=>'polling','note'=>'WPVibe suppresses reload inside builder edit sessions to avoid destroying editor state.');}
	private static function integrations(){$types=array_keys(WPVDMCP_Parity_Fields::block_types());$has=function($prefix)use($types){foreach($types as$n)if(0===strpos($n,$prefix))return true;return false;};return array('elementor'=>WPVDMCP_Compatibility::route_exists('/wpvibe/v1/elementor/save-page'),'beaver_builder'=>WPVDMCP_Compatibility::route_exists('/wpvibe/v1/beaver/save-page'),'bricks'=>WPVDMCP_Compatibility::route_exists('/wpvibe/v1/bricks/save-page'),'breakdance'=>WPVDMCP_Compatibility::route_exists('/wpvibe/v1/breakdance/save-page'),'kadence'=>$has('kadence/'),'generateblocks'=>$has('generateblocks/'),'generatepress'=>defined('GP_PREMIUM_VERSION')||class_exists('GeneratePress_Pro'),'divi'=>defined('ET_CORE_VERSION')||class_exists('ET_Builder_Plugin'),'seedprod'=>defined('SEEDPROD_VERSION')||class_exists('SeedProd_Lite'));}
	private static function seo_audit($args){$path=(string)($args['path']??'');if(''===$path)return new WP_Error('invalid_path','path is required.',array('status'=>400));if(!WPVDMCP_Compatibility::route_exists('/wpvibe/v1/rendered-html'))return new WP_Error('tool_unavailable','WPVibe rendered HTML route is unavailable.',array('status'=>404));$r=WPVDMCP_Tools::dispatch('POST','/wpvibe/v1/rendered-html',array(),array('path'=>$path));if(is_wp_error($r))return $r;$d=$r['data'];$html=is_array($d)?(string)($d['html']??$d['content']??''):(string)$d;$title=self::match('/<title[^>]*>(.*?)<\/title>/is',$html);$desc=self::match('/<meta[^>]+name=["\']description["\'][^>]+content=["\']([^"\']*)["\']/is',$html);if(!$desc)$desc=self::match('/<meta[^>]+content=["\']([^"\']*)["\'][^>]+name=["\']description["\']/is',$html);$canonical=self::match('/<link[^>]+rel=["\']canonical["\'][^>]+href=["\']([^"\']+)["\']/is',$html);$robots=self::match('/<meta[^>]+name=["\']robots["\'][^>]+content=["\']([^"\']*)["\']/is',$html);preg_match_all('/<h1\b/i',$html,$h1);preg_match_all('/<img\b(?![^>]*\balt\s*=)[^>]*>/i',$html,$missing_alt);preg_match_all('/<script[^>]+type=["\']application\/ld\+json["\']/i',$html,$schema);return array('path'=>$path,'title'=>html_entity_decode(strip_tags($title),ENT_QUOTES,'UTF-8'),'meta_description'=>$desc,'canonical'=>$canonical,'robots'=>$robots,'h1_count'=>count($h1[0]),'schema_blocks'=>count($schema[0]),'issues'=>array('missing_title'=>''===$title,'missing_meta_description'=>''===$desc,'missing_canonical'=>''===$canonical,'multiple_h1'=>count($h1[0])>1,'images_missing_alt'=>count($missing_alt[0])));}
	private static function match($regex,$html){return preg_match($regex,$html,$m)?trim($m[1]):'';}
	private static function provider($name,$args){$v=self::provider_value($name,$args);if(null===$v||false===$v)return new WP_Error('provider_unavailable','No user-owned provider is configured for '.$name.'.',array('status'=>501,'provider'=>$name));return $v;}
	private static function provider_value($name,$args){if(isset($GLOBALS['wpvdmcp_providers'][$name])&&is_callable($GLOBALS['wpvdmcp_providers'][$name]))return call_user_func($GLOBALS['wpvdmcp_providers'][$name],$args);if('pdf_text'===$name&&isset($GLOBALS['wpvdmcp_pdf_text']))return $GLOBALS['wpvdmcp_pdf_text'];if(function_exists('apply_filters'))return apply_filters('wpvdmcp_'.$name,null,$args);return null;}
	private static function tool($name,$description,$props){$required=array();foreach($props as$k=>&$p){if(!empty($p['_required'])){$required[]=$k;unset($p['_required']);}}unset($p);$schema=array('type'=>'object','properties'=>(object)$props,'additionalProperties'=>false);if($required)$schema['required']=$required;return array('name'=>$name,'description'=>$description,'inputSchema'=>$schema);}private static function strp($d,$r=false){return array('type'=>'string','description'=>$d,'_required'=>$r);}private static function intp($d,$r=false){return array('type'=>'integer','description'=>$d,'_required'=>$r);}
}
